parameters.jsCode:
const chunks = $items("Chunking Raw Data").map(item => item.json);
const semanticDocs = $items("Build Semantic Content").map(item => item.json);
const trigger = $('When Executed by Another Workflow').first().json;
const configSnapshot = trigger.configSnapshot || trigger.config_snapshot || {};

function countWords(text) {
  const matches = String(text || '').match(/[A-Za-z0-9]+(?:['-][A-Za-z0-9]+)*/g);
  return matches ? matches.length : 0;
}

function num(value) {
  const parsed = Number(value);
  return Number.isFinite(parsed) ? parsed : 0;
}

const embeddedCharacterCount = chunks.reduce((total, chunk) => {
  return total + String(chunk.pageContent || '').length;
}, 0);

const embeddedWordCount = chunks.reduce((total, chunk) => {
  return total + countWords(chunk.pageContent);
}, 0);

const estimatedEmbeddingTokens = Math.ceil(embeddedCharacterCount / 4);
const embeddingModel = configSnapshot.models?.embeddingModel || 'text-embedding-3-small';
const embeddingCostPerToken = String(embeddingModel).includes('large')
  ? 0.13 / 1_000_000
  : 0.02 / 1_000_000;
const embeddingCostUsd = estimatedEmbeddingTokens * embeddingCostPerToken;

const visionTokensInput = semanticDocs.reduce((total, doc) => total + (Number(doc.visionTokensInput) || 0), 0);
const visionTokensOutput = semanticDocs.reduce((total, doc) => total + (Number(doc.visionTokensOutput) || 0), 0);
const visionCostUsd = semanticDocs.reduce((total, doc) => total + (Number(doc.visionCostUsd) || 0), 0);
const visionUsageEstimated = semanticDocs.some(doc => Boolean(doc.visionUsageEstimated));

const extractionFiles = semanticDocs.map(doc => {
  const stats = doc.extractionStats || {};
  const warnings = Array.isArray(doc.warnings) ? doc.warnings.filter(Boolean).map(String) : [];
  return {
    fileName: doc.fileName || null,
    fileType: doc.fileType || null,
    docType: doc.docType || null,
    durationMs: num(stats.durationMs ?? stats.duration_ms ?? doc.durationMs ?? doc.extractionDurationMs),
    fileSizeBytes: num(stats.fileSizeBytes ?? stats.file_size_bytes ?? doc.fileSizeBytes),
    responseBytesEstimated: num(stats.responseBytesEstimated ?? stats.response_bytes_estimated ?? doc.responseBytesEstimated),
    warningCount: num(doc.warningCount ?? stats.warningCount ?? warnings.length),
    tableCount: num(doc.tableCount ?? stats.tableCount ?? stats.tablesExtracted),
    annotationCount: num(doc.annotationCount ?? stats.annotationCount ?? stats.annotationsExtracted),
    linkCount: num(doc.linkCount ?? stats.linkCount ?? stats.linksExtracted),
    visualCandidatesDetected: num(doc.visualCandidatesDetected ?? stats.visualCandidatesDetected),
    warnings: warnings.slice(0, 10),
  };
});

const extractionObservability = {
  durationMs: extractionFiles.reduce((total, file) => total + file.durationMs, 0),
  fileSizeBytes: extractionFiles.reduce((total, file) => total + file.fileSizeBytes, 0),
  responseBytesEstimated: extractionFiles.reduce((total, file) => total + file.responseBytesEstimated, 0),
  warningCount: extractionFiles.reduce((total, file) => total + file.warningCount, 0),
  tableCount: extractionFiles.reduce((total, file) => total + file.tableCount, 0),
  annotationCount: extractionFiles.reduce((total, file) => total + file.annotationCount, 0),
  linkCount: extractionFiles.reduce((total, file) => total + file.linkCount, 0),
  visualCandidatesDetected: extractionFiles.reduce((total, file) => total + file.visualCandidatesDetected, 0),
  warnings: extractionFiles.flatMap(file => file.warnings.map(warning => (file.fileName || 'document') + ': ' + warning)).slice(0, 25),
  files: extractionFiles,
};

const tokensInput = visionTokensInput + estimatedEmbeddingTokens;
const tokensOutput = visionTokensOutput;
const tokensTotal = tokensInput + tokensOutput;
const estimatedCostUsd = visionCostUsd + embeddingCostUsd;

return [
  {
    json: {
      totalChunksStored: chunks.length,
      tokensInput,
      tokensOutput,
      tokensTotal,
      estimatedCostUsd: Number(estimatedCostUsd.toFixed(6)),
      extractionObservability,
      tokenUsage: {
        accounting: 'actual_vision_when_available_plus_estimated_embeddings',
        visionModel: 'gpt-4o-mini',
        visionTokensInput,
        visionTokensOutput,
        visionTokensTotal: visionTokensInput + visionTokensOutput,
        visionCostUsd: Number(visionCostUsd.toFixed(6)),
        visionUsageEstimated,
        embeddingModel,
        embeddedCharacterCount,
        embeddedWordCount,
        estimatedEmbeddingTokens,
        embeddingCostUsd: Number(embeddingCostUsd.toFixed(6)),
        tokensInput,
        tokensOutput,
        tokensTotal,
        estimatedCostUsd: Number(estimatedCostUsd.toFixed(6)),
        extractionObservability
      }
    }
  }
];

const data = $json;
const trigger = $('When Executed by Another Workflow').first().json;

function firstFileKey(files) {
  const keys = Object.keys(files || {});
  return keys[0] || 'unknown';
}

function documentTypeFromFileKey(key) {
  const value = String(key || '').toLowerCase();
  if (['brd', 'frd', 'hld', 'lld'].includes(value)) return value.toUpperCase();
  if (value.startsWith('transcript')) return 'TRANSCRIPT';
  if (value === 'image' || value.startsWith('image')) return 'UI_DESIGN';
  return value ? value.toUpperCase() : 'UNKNOWN';
}

function toDate(value) {
  const date = value ? new Date(value) : null;
  return date && !Number.isNaN(date.getTime()) ? date : null;
}

const jobId = data.job_id;
const projectName = data.input?.projectName;
const files = data.input?.files || {};
const fileKeys = Object.keys(files);
const totalFiles = fileKeys.length;
const fileKey = firstFileKey(files);
const documentType = documentTypeFromFileKey(fileKey);
const configSnapshot = data.config_snapshot || trigger.configSnapshot || trigger.config_snapshot || {};
const tokenUsage = data.output?.tokenUsage || {};
const extractionObservability = data.output?.extractionObservability || tokenUsage.extractionObservability || {};
const completedAt = new Date();
const completedAtFromDb = toDate(data.updated_at);
const createdAt = toDate(data.created_at);
const durationMs = createdAt ? Math.max(0, (completedAtFromDb || completedAt).getTime() - createdAt.getTime()) : null;
const embeddedWordCount = Number(tokenUsage.embeddedWordCount) || 0;
const wordCount = embeddedWordCount || null;

console.log("INGESTION COMPLETED:", {
  jobId,
  projectName,
  totalFiles,
  fileKeys,
  documentType,
  durationMs,
  wordCount,
  projectId: data.project_id || trigger.projectId || trigger.project_id || null,
  requestedBy: data.requested_by || trigger.requestedBy || trigger.requested_by || null,
  tokensTotal: tokenUsage.tokensTotal || 0,
  estimatedCostUsd: tokenUsage.estimatedCostUsd || 0,
  warningCount: extractionObservability.warningCount || 0
});

return [
  {
    json: {
      jobId,
      projectName,
      totalFiles,
      fileKeys,
      fileKey,
      documentType,
      logType: "INGESTION_COMPLETED",
      totalChunksStored: data.output?.totalChunksStored || 0,
      durationMs,
      wordCount,
      tokensInput: Number(tokenUsage.tokensInput) || 0,
      tokensOutput: Number(tokenUsage.tokensOutput) || 0,
      tokensTotal: Number(tokenUsage.tokensTotal) || 0,
      estimatedCostUsd: Number(tokenUsage.estimatedCostUsd) || 0,
      tokenUsage,
      extractionObservability,
      projectId: data.project_id || trigger.projectId || trigger.project_id || null,
      requestedBy: data.requested_by || trigger.requestedBy || trigger.requested_by || null,
      settingsVersion: data.settings_version || trigger.settingsVersion || trigger.settings_version || null,
      configSnapshot,
      environmentKey: configSnapshot.environment?.key || trigger.environment || 'local',
      completedAt: completedAt.toISOString()
    }
  }
];

const items = $input.all();

if (!items.length) {
  return [];
}

const clamp = (value, fallback, minimum, maximum) => {
  const parsed = Number(value);
  return Number.isFinite(parsed) ? Math.max(minimum, Math.min(maximum, parsed)) : fallback;
};

const runtimeConfig = items[0].json.configSnapshot?.microservices?.vision || {};
const maxImages = clamp(runtimeConfig.maxImagesPerJob, 80, 1, 500);
const batchSize = clamp(runtimeConfig.batchSize, 5, 1, 50);
const deferOverflowVisuals = runtimeConfig.deferOverflowVisuals !== false;

const prioritized = items.slice().sort((left, right) => {
  const scoreDelta = (Number(right.json.priorityScore) || 0) - (Number(left.json.priorityScore) || 0);
  if (scoreDelta !== 0) return scoreDelta;

  const pageDelta = (Number(left.json.pageNumber) || 0) - (Number(right.json.pageNumber) || 0);
  if (pageDelta !== 0) return pageDelta;

  return (Number(left.json.imageIndex) || 0) - (Number(right.json.imageIndex) || 0);
});

const retained = prioritized.slice(0, maxImages);
const deferredCount = Math.max(0, prioritized.length - retained.length);

if (deferredCount > 0) {
  console.log(`Vision candidate count (${prioritized.length}) exceeds configured limit ${maxImages}. Retaining ${retained.length} candidates and deferring ${deferredCount}.`);
}

return retained.map((item, index) => ({
  json: {
    ...item.json,
    totalImagesInDocument: prioritized.length,
    imageLimitApplied: deferredCount > 0,
    processedImagesInJob: retained.length,
    deferredImagesInJob: deferredCount,
    visionMaxImagesPerJob: maxImages,
    visionBatchSize: batchSize,
    deferOverflowVisuals,
    visionProcessingRank: index + 1
  }
}));
